-- Keep the original 597 TACO IDs. Additional references use their own identity range.
alter table public.taco_foods alter column id add generated by default as identity(start with 100000);
alter table public.taco_foods add column reference_source text not null default 'taco' check(reference_source in ('taco','tbca','ai')),
 add column reference_code text,add column reference_url text,add column resolution_model text,
 add column is_estimate boolean not null default false,add column retrieved_at timestamptz not null default now();
create unique index food_reference_source_code on public.taco_foods(reference_source,reference_code) where reference_code is not null;
grant select on public.taco_foods to service_role;

create table public.food_reference_matches(lookup_key text primary key,food_id integer not null references public.taco_foods(id),created_at timestamptz not null default now());
alter table public.food_reference_matches enable row level security;
revoke all on public.food_reference_matches from anon,authenticated;
grant select on public.food_reference_matches to service_role;
create policy reference_service_read on public.food_reference_matches for select to service_role using(true);
alter table public.diet_items add column portion_estimated boolean not null default false;
alter table public.patient_food_substitutions add column reference_details jsonb not null default '{}';

create function public.cache_food_reference(p_key text,p_reference jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare f public.taco_foods;src text:=p_reference->>'reference_source';code text:=nullif(p_reference->>'reference_code','');energy numeric;begin
 if length(p_key) not between 1 and 250 then raise exception 'Alimento inválido';end if;
 perform pg_advisory_xact_lock(hashtextextended('food-reference:'||p_key,0));
 select t.* into f from public.food_reference_matches m join public.taco_foods t on t.id=m.food_id where m.lookup_key=p_key;
 if found then return to_jsonb(f);end if;
 if src='taco' then
  select * into f from public.taco_foods where id=(p_reference->>'id')::integer and reference_source='taco' and kcal_per_100g>0;
  if not found then raise exception 'Referência inválida';end if;
 else
  energy:=(p_reference->>'kcal_per_100g')::numeric;
  if src not in ('tbca','ai') or coalesce(energy,0)<=0 or energy>1000 or length(trim(p_reference->>'name')) not between 1 and 500 then raise exception 'Referência inválida';end if;
  if src='tbca' and (code is null or code!~'^BR[A-Z][0-9]{4}[A-Z]$' or coalesce(p_reference->>'reference_url','')!~'^https://(www\.)?tbca\.net\.br/base-dados') then raise exception 'Fonte inválida';end if;
  if code is not null then select * into f from public.taco_foods where reference_source=src and reference_code=code;end if;
  if f.id is null then
   insert into public.taco_foods(name,category,kcal_per_100g,source_version,reference_source,reference_code,reference_url,resolution_model,is_estimate)
   values(trim(p_reference->>'name'),coalesce(nullif(p_reference->>'category',''),'Outros alimentos'),energy,case when src='tbca' then 'TBCA:'||code else 'AI-ESTIMATE' end,src,code,p_reference->>'reference_url',p_reference->>'resolution_model',src='ai') on conflict(reference_source,reference_code) where reference_code is not null do update set reference_code=excluded.reference_code returning * into f;
  end if;
 end if;
 insert into public.food_reference_matches(lookup_key,food_id) values(p_key,f.id);
 return to_jsonb(f);
end $$;
revoke all on function public.cache_food_reference(text,jsonb) from public,anon,authenticated;
grant execute on function public.cache_food_reference(text,jsonb) to service_role;

create function public.bind_food_reference(p_item uuid,p_patient uuid,p_food integer,p_grams numeric,p_estimated boolean,p_name text,p_quantity text,p_unit text) returns jsonb language plpgsql security definer set search_path='' as $$
declare i public.diet_items;begin
 select x.* into i from public.diet_items x join public.diet_meals m on m.id=x.meal_id join public.diets d on d.id=m.diet_id where x.id=p_item and d.patient_id=p_patient and d.status='active' for update of x;
 if i.id is null then raise exception 'Alimento fora do plano atual' using errcode='42501';end if;
 if i.food_name is distinct from p_name or i.quantity is distinct from p_quantity or i.unit is distinct from p_unit then raise exception 'O plano mudou. Atualize e tente novamente.' using errcode='40001';end if;
 if coalesce(p_grams,0)<=0 or p_grams>100000 or not exists(select 1 from public.taco_foods where id=p_food and kcal_per_100g>0) then raise exception 'Porção inválida';end if;
 -- Attribute the narrow metadata update to the authenticated patient who requested it.
 perform set_config('request.jwt.claims',jsonb_build_object('sub',(select user_id from public.profiles where id=p_patient),'role','authenticated')::text,true);
 update public.diet_items set taco_food_id=p_food,portion_g=p_grams,portion_estimated=p_estimated where id=p_item returning * into i;
 return to_jsonb(i);
end $$;
revoke all on function public.bind_food_reference(uuid,uuid,integer,numeric,boolean,text,text,text) from public,anon,authenticated;
grant execute on function public.bind_food_reference(uuid,uuid,integer,numeric,boolean,text,text,text) to service_role;

create function public.snapshot_food_reference() returns trigger language plpgsql security definer set search_path='' as $$
declare s public.taco_foods;t public.taco_foods;begin
 select * into s from public.taco_foods where id=new.source_food_id;select * into t from public.taco_foods where id=new.target_food_id;
 new.source_version:=case when s.source_version=t.source_version then s.source_version else s.source_version||' → '||t.source_version end;
 new.reference_details:=jsonb_build_object('source',jsonb_build_object('source',s.reference_source,'code',s.reference_code,'url',s.reference_url,'estimated',s.is_estimate),'target',jsonb_build_object('source',t.reference_source,'code',t.reference_code,'url',t.reference_url,'estimated',t.is_estimate),'portion_estimated',coalesce((select portion_estimated from public.diet_items where id=new.item_id),false));
 return new;
end $$;
revoke all on function public.snapshot_food_reference() from public,anon,authenticated;
create trigger snapshot_food_reference before insert or update on public.patient_food_substitutions for each row execute function public.snapshot_food_reference();

-- Preserve reference snapshots when a previously unbound food is resolved.
create or replace function public.save_food_substitution(p_operation uuid,p_item uuid,p_target integer,p_date date,p_expected uuid default null)
 returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=public.current_profile_id();i public.diet_items;s public.taco_foods;t public.taco_foods;
 pid uuid;diet_status text;current_row public.patient_food_substitutions;history public.clinical_records;day date:=(now() at time zone 'America/Sao_Paulo')::date;
begin
 if actor is null or p_operation is null then raise exception 'Autenticação necessária' using errcode='42501';end if;
 select * into i from public.diet_items where id=p_item;
 select d.patient_id,d.status into pid,diet_status from public.diets d join public.diet_meals m on m.diet_id=d.id where m.id=i.meal_id;
 if pid is distinct from actor then raise exception 'Alimento não autorizado' using errcode='42501';end if;
 if p_date is distinct from day or diet_status<>'active' then raise exception 'Escolha um alimento do seu plano atual para hoje';end if;
 perform pg_advisory_xact_lock(hashtextextended(pid::text||i.meal_id::text||p_date::text,0));
 select * into current_row from public.patient_food_substitutions where patient_id=pid and item_id=i.id and check_date=p_date for update;
 select * into history from public.clinical_records where id=p_operation;
 if found then
  if history.created_by is distinct from actor or history.kind<>'checkin' or history.payload->>'category' is distinct from 'meal_substitution' or history.payload->>'action' is distinct from 'replace' or history.payload->>'item_id' is distinct from p_item::text or history.payload->>'target_food_id' is distinct from p_target::text or history.payload->>'date' is distinct from p_date::text then raise exception 'Identificador de envio já utilizado';end if;
  return jsonb_build_object('substitution',case when current_row.id is null then null else to_jsonb(current_row) end,'replayed',true);
 end if;
 if current_row.id is distinct from p_expected then raise exception 'A troca foi alterada em outra janela. Atualize antes de continuar.' using errcode='40001';end if;
 select * into s from public.taco_foods where id=i.taco_food_id;select * into t from public.taco_foods where id=p_target;
 if s.id is null or t.id is null or coalesce(i.portion_g,0)<=0 or coalesce(s.kcal_per_100g,0)<=0 or coalesce(t.kcal_per_100g,0)<=0 or s.id=t.id then raise exception 'Não há referência e peso válidos para esta troca';end if;
 insert into public.patient_food_substitutions(id,patient_id,meal_id,item_id,check_date,source_food_id,target_food_id,original_name,original_quantity,source_name,target_name,source_grams,target_grams,source_kcal_per_100g,target_kcal_per_100g,energy_kcal)
 values(p_operation,pid,i.meal_id,i.id,p_date,s.id,t.id,i.food_name,concat_ws(' ',nullif(i.quantity,''),nullif(i.unit,'')),s.name,t.name,i.portion_g,i.portion_g*s.kcal_per_100g/t.kcal_per_100g,s.kcal_per_100g,t.kcal_per_100g,i.portion_g*s.kcal_per_100g/100)
 on conflict(patient_id,item_id,check_date) do update set id=excluded.id,source_food_id=excluded.source_food_id,original_name=excluded.original_name,original_quantity=excluded.original_quantity,source_name=excluded.source_name,source_grams=excluded.source_grams,source_kcal_per_100g=excluded.source_kcal_per_100g,energy_kcal=excluded.energy_kcal,target_food_id=excluded.target_food_id,target_name=excluded.target_name,target_grams=excluded.target_grams,target_kcal_per_100g=excluded.target_kcal_per_100g,created_at=now()
 returning * into current_row;
 insert into public.patient_saved_substitutions(patient_id,source_food_id,target_food_id) values(pid,s.id,t.id)
 on conflict(patient_id,source_food_id,target_food_id) do update set last_used_at=now();
 -- A planned replacement does not claim that the patient already ate it.
 delete from public.patient_item_checks where patient_id=pid and item_id=i.id and check_date=p_date;
 insert into public.clinical_records(id,patient_id,kind,payload,created_by)
 values(p_operation,pid,'checkin',to_jsonb(current_row)||jsonb_build_object('category','meal_substitution','action','replace','date',p_date),actor);
 return jsonb_build_object('substitution',to_jsonb(current_row),'replayed',false);
end $$;
